from datetime import datetime, timedelta
import math


class ParkingMeter:
    def __init__(self, hourly_rate: float = 4.0) -> None:
        self.hourly_rate = hourly_rate
        self._collected = 0.0

    def fee(self, entry: datetime, exit: datetime) -> float:
        if exit < entry:
            raise ValueError("Exit time cannot be earlier than entry time.")

        duration = exit - entry
        total_seconds = duration.total_seconds()

        # Stays of at most 15 minutes are free
        if total_seconds <= 15 * 60:
            return 0.0

        # Stays longer than 24 hours are charged a flat penalty
        if total_seconds > 24 * 60 * 60:
            return 200.00

        # Every started hour is charged as a full hour
        hours = math.ceil(total_seconds / 3600)
        total = hours * self.hourly_rate
        return round(total, 2)

    def record(self, entry: datetime, exit: datetime) -> float:
        amount = self.fee(entry, exit)
        self._collected += amount
        return amount

    def total_collected(self) -> float:
        return round(self._collected, 2)

    def estimate(self, hours: int) -> float:
        if hours < 0:
            raise ValueError("Hours cannot be negative.")
        if hours == 0:
            return 0.0
        # Reuse the fee logic by simulating an entry/exit pair
        # spaced exactly `hours` apart.
        entry = datetime(2000, 1, 1, 0, 0, 0)
        exit = entry + timedelta(hours=hours)
        return self.fee(entry, exit)

    def receipt(self, entry: datetime, exit: datetime) -> str:
        if exit < entry:
            raise ValueError("Exit time cannot be earlier than entry time.")
        amount = self.fee(entry, exit)
        duration = exit - entry
        total_minutes = int(duration.total_seconds() // 60)
        return f"Duration: {total_minutes} minutes | Fee: ${amount:.2f}"
```

